import pandas as pd

path = "英语口语30天计划.xlsx"

# Coverage analysis
weeks = {}
themes = []
for sheet in ['30天口语计划']:
    df = pd.read_excel(path, sheet_name=sheet, header=2)
    # count days by week
    for _, r in df.iterrows():
        week = r['周']
        if pd.notna(week):
            weeks.setdefault(week, 0)
            weeks[week] += 1
            if pd.notna(r['主题']):
                themes.append((week, r['天'], r['主题']))

print("Days per week:", weeks)
print("Total days:", sum(weeks.values()))
print("\nAll themes:")
for w,d,t in themes:
    print(f"  {w} {d}: {t}")

